mkdir -p /tmp/verify/packaging && cat > /tmp/verify/packaging/cmp_reqs.py <<'EOF'
import re, subprocess, sys

def norm(n): return re.sub(r'[-_.]+', '-', n).lower()

installed = {}
out = subprocess.check_output([sys.executable, '-m', 'pip', 'list', '--format=freeze'],
                              stderr=subprocess.DEVNULL).decode()
for line in out.splitlines():
    if '==' in line:
        n, v = line.split('==', 1)
        installed[norm(n)] = v.strip()

reqs = {}
with open('/workspace/requirements.txt') as fh:
    for line in fh:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        m = re.match(r'^([A-Za-z0-9_.\-]+)\s*==\s*(.+)$', line)
        if not m:
            print('UNPARSED LINE:', repr(line)); continue
        reqs[norm(m.group(1))] = (m.group(1), m.group(2).strip())

print('=== MISMATCHES (pinned != installed) ===')
bad = 0
for k, (raw, ver) in sorted(reqs.items()):
    if k not in installed:
        print('  NOT INSTALLED AT ALL: %s==%s' % (raw, ver)); bad += 1
    elif installed[k] != ver:
        print('  MISMATCH: %s pinned==%s but installed==%s' % (raw, ver, installed[k])); bad += 1
if not bad:
    print('  (none)')

print()
print('=== SPEC CORE LIBS: pinned? installed? ===')
spec = ['Flask', 'Flask-SQLAlchemy', 'SQLAlchemy', 'Werkzeug', 'itsdangerous',
        'WTForms', 'Flask-Login', 'Flask-HTTPAuth', 'Flask-WTF', 'Flask-Mail',
        'Flask-Migrate', 'Flask-Bootstrap', 'Flask-Moment', 'Flask-PageDown',
        'bleach', 'Markdown', 'Faker', 'Jinja2', 'MarkupSafe', 'blinker',
        'html5lib', 'webencodings', 'six', 'python-dotenv']
for s in spec:
    k = norm(s)
    print('  %-20s installed=%-12s pinned=%s' % (
        s, installed.get(k, 'NO'), reqs.get(k, ('-', 'MISSING-FROM-REQS'))[1]))

print()
print('=== INSTALLED but NOT in requirements.txt ===')
for k, v in sorted(installed.items()):
    if k not in reqs:
        print('  %s==%s' % (k, v))
EOF
cd /tmp/verify/packaging && python3 cmp_reqs.py
